/**
 * A faixa foi normalizada; este ganho a leva de volta ao volume combinado com a trilha no volume
 * padrão (respiração a 15% e o zumbido a 10% da trilha).
 */
export const HURT_SOUND_GAIN = 0.04051;

/** As amostras (−1..1) a partir do µ-law. */
export function hurtSoundSamples() {
  const bin = globalThis.atob(HURT_SOUND_MULAW);
  const out = new Float32Array(bin.length);
  const mu = 255;
  for (let i = 0; i < bin.length; i += 1) {
    const q = (bin.charCodeAt(i) / 255) * 2 - 1;
    out[i] = (Math.sign(q) * ((1 + mu) ** Math.abs(q) - 1)) / mu;
  }
  return out;
}
